"""Render the PIT NC sort benchmark JSON as a Russian Markdown report."""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('directory', type=Path)
    args = parser.parse_args()
    d = args.directory
    report = json.loads((d/'results.json').read_text())
    algorithms = ['shell', 'insertion', 'merge', 'quick', 'radix']
    rows = report['results']
    lines = ['# NC: сравнение сортировок индексов', '',
             'Emu80, Intel 8080 и ВИ53 2 МГц. Это измерения модели, не физического компьютера. Для каждого сочетания выполнено три прогона; в таблицах приведена медиана в миллисекундах. Исходные счётчики и все 16-байтные записи сохранены в results.json.', '',
             'Измеряется только сортировка уже заполненного байтового индекса. ВИ53 читается непосредственно до и после алгоритма. Получение списка DOS, выбор диска, подготовка шрифта, рисование и заполнение начального индекса не входят в интервал. Нормализация ключей измеряется отдельно: копирование 11 байтов имени/расширения с BIOS upperCase и подготовка ранга записи в отдельном 16-байтном буфере. Исходный список FILE_INFO не меняется.', '',
             'Для Шелла, слияния, quicksort и radix шаг счётчика 0,128 мс, диапазон 8,389 с. Для вставок делитель увеличен: шаг 2,048 мс, диапазон 134,218 с. Первые короткие замеры вставок исключены и повторены с увеличенным диапазоном. Накладные расходы чтения таймера не вычитались; доли миллисекунды не следует трактовать как точность физического оборудования.', '',
             'Порядок ключей независим: имя[8] + расширение[3] либо расширение[3] + имя[8], включая дополняющие пробелы. Перед текстом сравнивается ранг: корень, родитель, каталог, файл. Равные полные ключи упорядочиваются по исходному номеру записи. Для radix это обеспечивается стабильными проходами по исходному индексу.', '',
             'Сравниваются исходный Shell с шагами N/2,…,1, вставки (тот же компаратор и шаг 1), стабильное слияние снизу вверх, quicksort со средним опорным элементом и разбиением Lomuto, стабильный LSD radix с 256 счётчиками. Сравнительные алгоритмы используют общий компаратор NC; в подготовленном варианте из него исключены вызовы upperCase. Radix проходит 11 байтов ключа и ранг без строкового компаратора. В сыром radix upperCase вызывается при чтении разряда; в подготовленном читается готовый байт.', '',
             'В стенде адрес базы массива задаётся напрямую; панельная адресация NC заменена одинаковым коротким адаптером для всех кандидатов. Поэтому отдельно измерен неизменённый buildFileIndex из загруженного NC: он включает штатную адресацию и заполнение индекса. Его результаты точнее характеризуют текущую задержку оболочки.', '']
    memory_path = d/'nc-memory.json'
    if memory_path.exists():
        memory = json.loads(memory_path.read_text())
        lines += [f"По просьбе пользователя пререндер NC отключён и его буфер 10 КиБ удалён из размещения. В текущей сборке свободна область {memory['nc_end']:04X}h–{memory['memory_end']-1:04X}h ({memory['free_bytes']} байт); после запуска база пререндера BIOS равна нулю. Теперь отдельный буфер нормализованных ключей помещается в память NC. Результаты сортировок от состояния шрифтов не зависят: вызовов рендера внутри интервала нет. Рабочий алгоритм NC пока остаётся Shell; остальные реализации находятся в изолированном стенде.", '']
    list_path = d/'list-results.json'
    if list_path.exists():
        listing = json.loads(list_path.read_text())
        lines += ['## Получение списка от DOS', '',
                  'ВИ53 охватывает один настоящий MXOS_CALL DIR_OP_LIST: обход FAT-каталога, создание компактных FILE_INFO в DOS и доставку результата в MAIN. Сортировка, рисование, выбор диска, установка каталога и remount исключены из этого интервала. Все возвращённые записи и терминатор сверяются побайтно с исходным кэшем NC, снятым до замены MAIN кодом стенда.', '',
                  '«Холодный корень» означает инвалидирование кэша выбранного диска штатным mountVolume вне интервала; сам том уже смонтирован, BPB подготовлен. «Тёплый корень» — повторный DIR_OP_LIST без инвалидирования. Оба варианта действительно вызывают DOS; собственный кэш каталогов NC обходится. Три повтора, медианы в миллисекундах, Emu80 и ВИ53 2 МГц.', '',
                  '| Записей H: | Только LIST, холодный | Только LIST, тёплый | A:→H: + SET + LIST, холодный | A:→H: + SET + LIST, тёплый |',
                  '|---:|---:|---:|---:|---:|']
        for count in (127,250):
            values = {(r['operation'],r['cache']):r['median_ms'] for r in listing['results'] if r['count']==count}
            fields = [values[(op,cache)] for op in ('list','select+set+list') for cache in ('cold-root','warm-root')]
            lines.append(f'| {count} | '+' | '.join(f'{v:.1f}' for v in fields)+' |')
        lines += ['', 'Отдельно выбор H: после A: и установка корня без LIST заняли 32,512 мс. Это цена реального переключения выбранного диска и контекста; она не является временем одного пустого MXOS_CALL и не относится автоматически к повторному выбору уже активного H:.', '',
                  'NC передаёт capacity=255 и skip=0 одним запросом. DOS обходит каталог за один проход и возвращает до 4081 байта (255×16 + FFh); список 250 записей занимает 4001 байт и целиком помещается в одну пачку 4096 байт. Отдельных MAIN→DOS запросов для каждого файла нет. При попадании в собственный кэш NC DIR_OP_LIST вообще не выполняется.', '']
    lines += ['## Накладные расходы компаратора', '',
              'В рабочем NC вызывается CALL ncCompareFiles. Внутри идут fileInfoAtIndex, два ncFileRank и ncComparePart; сырой ncComparePart дважды вызывает BIOS upperCase на каждую просмотренную пару символов. Режим загружается в ncSortMode при начале сортировки и проверяется внутри каждого сравнения записей одной группы. Переключения указателя на компаратор нет. При смене режима NC сначала ищет подходящий сохранённый индекс, иначе перестраивает его.', '',
              'Один CALL и обычный RET занимают 27 тактов 8080, то есть 13,5 мкс при 2 МГц. Для 2359 сравнений Shell на H-root-250 это около 31,8 мс только на внешний вызов. Заметно больше дают сохранение регистров, повторное определение адреса каталога через активную панель, вычисление ранга и вызовы преобразования регистра внутри посимвольного цикла.', '',
              'Возможные оптимизации пока не внесены в рабочий алгоритм: определить базу массива один раз перед сортировкой; выбирать специализированные ветви 8+3/3+8 до цикла; сократить PUSH/POP и вложенные вызовы; для сырого текста пропускать upperCase при побайтно равных символах, а разные символы сравнивать после штатного преобразования. Для radix — пропускать постоянные разряды, ограничивать диапазон счётчиков фактически используемыми значениями и чередовать входной/выходной индексные буферы вместо копирования результата после каждого прохода. Пропуск постоянных разрядов сохраняет относительный порядок: такой проход ничего не меняет.', '']
    actual = []
    for path in (d/'actual-nc.json', d/'actual-nc-250.json'):
        if path.exists():
            actual += json.loads(path.read_text())
    if actual:
        lines += ['## Текущий NC без замены алгоритма', '', '| Записей H: | По имени, мс | По расширению, мс |', '|---:|---:|---:|']
        for count in sorted({r['count'] for r in actual}):
            values = {r['mode']:r['median_ms'] for r in actual if r['count']==count}
            lines.append(f"| {count} | {values.get(1,0):.1f} | {values.get(2,0):.1f} |")
        lines.append('')
    profile_path = d/'profile.json'
    if profile_path.exists():
        profile = json.loads(profile_path.read_text())
        lines += ['## Почему quicksort не всегда первый', '',
                  'Это конкретная реализация quicksort на 8080: опорный элемент берётся по среднему индексу, используется разбиение Lomuto, короткие поддиапазоны не переключаются на вставки. Средний индекс не гарантирует близкого к медиане значения ключа. Процедура обмена не исключает обмен индекса с самим собой. Поэтому число сравнений, обменов и расходов на обработку поддиапазонов зависит от входного порядка.', '',
                  'Слияние обходит подсписки последовательно, переносит дешёвые байтовые индексы и в этих случаях выполняет меньше дорогих сравнений имён. Quicksort остаётся алгоритмом общего назначения, но его средняя сложность не означает минимального времени на любом входе и на любой реализации процессора. Эти результаты не характеризуют все возможные реализации quicksort.', '',
                  'Счётчики ниже сняты отдельно с инструментированной копии в модели z88dk-ticks. Каждая такая копия проверяется по тому же эталону сортировки. Инструментирование не включено в версии, измеряемые ВИ53. «Символы» — пары позиций имени/расширения, просмотренные компаратором, без ранга записи.', '',
                  '| Набор, режим 3+8 | Алгоритм | Сравнения записей | Символы | Вызовы обмена quicksort |',
                  '|---|---|---:|---:|---:|']
        for name in ('H-root-250','small-random-32','small-random-64','small-random-128'):
            for r in profile:
                if r['dataset']==name and r['mode']==2:
                    lines.append(f"| {name} | {r['algorithm']} | {r['comparisons']} | {r['character_pairs']} | {r['quick_swap_calls']} |")
        lines += ['', 'Каталоги не выделяются в отдельный список. В общей таблице индексов меньший ранг идёт раньше: 0 — корень, 1 — родитель, 2 — каталог, 3 — файл. В сравнительных алгоритмах ранг вычисляется перед именами; в подготовленном radix хранится готовым байтом. При совпадении ранга используется полный ключ 8+3 либо 3+8, включая пробелы. В режиме без сортировки ранг не применяется.', '']
    columns = [r for r in rows if r['algorithm']=='radix-columns']
    if columns:
        lines += ['## Поразрядные ключи в отдельных массивах', '',
                  'Radix-columns хранит каждую из 11 позиций имени/расширения в отдельном массиве на 256 байт и ранг в ещё одном массиве. Индекс записи сразу адресует один байт разряда: нет строкового компаратора, вызова upperCase при сортировке и умножения индекса на размер FILE_INFO. Оба режима используют один набор подготовленных разрядов; меняется только порядок проходов. Полезные данные ключей занимают 12×256 = 3072 байта; в данном стенде между расширением и рангом оставлена одна неиспользуемая страница, поэтому адресный диапазон — 3328 байт. Дополнительно нужны 256 байт счётчиков и 256 байт временного индекса.', '',
                  '| Набор | Режим | Только сортировка, мс | Подготовка, мс | Сумма, мс |',
                  '|---|---|---:|---:|---:|']
        for r in columns:
            lines.append(f"| {r['dataset']} | {'8+3' if r['mode']==1 else '3+8'} | {r['median_ms']:.1f} | {r['preparation_ms']:.1f} | {r['median_ms']+r['preparation_ms']:.1f} |")
        lines.append('')
    for mode, title in ((1, 'По имени: 8+3'), (2, 'По расширению: 3+8')):
        lines += ['## '+title, '', 'В ячейках: сырой буфер / подготовленный буфер, мс. Подготовка в эти числа не входит.', '',
                  '| Набор | N | Shell | Вставки | Слияние | Quicksort | Radix | Подготовка, мс |',
                  '|---|---:|---:|---:|---:|---:|---:|---:|']
        for name, dataset in report['datasets'].items():
            matching = [r for r in rows if r['dataset']==name and r['mode']==mode]
            if not matching:
                continue
            fields = []
            for algorithm in algorithms:
                pair = {r['prepared']:r['median_ms'] for r in matching if r['algorithm']==algorithm}
                fields.append(' / '.join(f'{pair[p]:.1f}' if p in pair else '—' for p in (False, True)))
            prep = next((r['preparation_ms'] for r in matching if r['prepared']), 0)
            lines.append(f"| {name} | {dataset['count']} | "+' | '.join(fields)+f' | {prep:.1f} |')
        lines.append('')
    lines += ['## Состав и проверка', '',
              'H-root — настоящий исходный корень H: со 127 записями. H-root-250 получен из него добавлением 111 пустых файлов с расширениями TXT/ASM/BIN/DAT/CFG/INI/LOG/OBJ/MAP/HLP и 12 пустых каталогов SRTDIR00…SRTDIR03 с расширениями ASM/TXT/RKS. У каждого каталога есть собственный кластер с `.` и `..`. Корневой каталог тестовой копии увеличен со 128 до 256 мест с переносом области данных и сохранением номеров кластеров. Независимый FAT-обход подтвердил сохранность исходных файлов и отсутствие потерянных цепочек. Основные образы и манифесты не менялись.', '',
              'SRTDIR00.ASM открыт штатными клавишами NC: внутри видны только два служебных пункта, возврат в корень восстановил 250 записей. Результат — directory-ui.json; снимки — empty-directory-with-extension.png и H-root-250.png. Сам сборщик образов пока создаёт только каталоги, подразумеваемые путями файлов; явные пустые каталоги манифестом не задаются. Для этого теста они добавлены отдельным nc-sort-image.py.', '',
              'random-* — фиксированное перемешивание (seed 8080), общие префиксы имён, четыре варианта расширений и каталоги. small-random-32/64/128 используют ту же схему имён и расширений, каждый набор перемешивается независимо с seed 8080; каталоги — каждая девятая запись до перемешивания. Это новые наборы; прежний random-128 сохраняется отдельно. sorted-255 и reverse-255 упорядочены по полному ключу 3+8; для режима 8+3 это отдельные входы, а не обещание предварительной сортировки. ties-koi8 проверяет каталоги, служебные пункты, одинаковые имена, различия регистра и русские буквы, включая Ё/ё.', '',
              'После каждого прогона результат сопоставляется с независимым Python-эталоном для текущего режима. Дополнительно проверяются терминатор FFh и неизменность всех исходных записей. Преобразование upperCase в эталоне повторяет текущую реализацию BIOS. Все тестовые экземпляры видимы, звук ВИ53 и мониторинг ленты выключены; экземпляры закрываются в finally.', '',
              '## Воспроизведение', '', '```powershell',
              'python scripts/emu80/benchmark-nc-sort.py',
              'python scripts/emu80/benchmark-nc-sort.py --append --fill-h --h-only',
              'python scripts/emu80/benchmark-nc-sort.py --append --baseline-only',
              'python scripts/emu80/benchmark-nc-sort.py --append --baseline-only --fill-h',
              'python scripts/emu80/benchmark-nc-sort.py --append --sizes 32 64 128',
              'python scripts/emu80/profile-nc-sort.py',
              'python scripts/emu80/benchmark-nc-list.py',
              'python scripts/emu80/report-nc-sort.py docs/nc/sort-benchmark-2026-11-11',
              '```', '',
              'Для запуска нужен свободный MCP-порт 19781. Скрипт создаёт собственный runtime .local/nc-sort-benchmark-runtime; к чужим экземплярам не подключается. benchRun заменяет MAIN тестовой машины только после загрузки NC и снятия списка H:. Это прямой стенд алгоритмов и таймера, а не проверка ввода команд NC.', '']
    (d/'report.md').write_text('\n'.join(lines), encoding='utf-8')
    print(d/'report.md')


if __name__ == '__main__':
    main()
